// No-flicker compact pillow block (6204: bore 20mm, OD 47mm, width 14mm)
$fn = 96;
eps = 0.05;

// Size
base_len = 130;
base_width = 30;
base_thick = 8;

center_height = 40;
housing_od = 63;
housing_width = 26;

// Bearing — 6204: bore 20mm, OD 47mm, width 14mm
bearing_od = 47;
bearing_id = 20;
bearing_width = 14;
clearance = 0.35;

// Bolts
bolt_dia = 7;
bolt_spacing = 90;
counterbore_dia = 13;
counterbore_depth = 3;

module body() {
    union() {
        // Base
        hull() {
            translate([-base_len/2 + 10, 0, base_thick/2])
                cylinder(d=20, h=base_thick, center=true);

            translate([ base_len/2 - 10, 0, base_thick/2])
                cylinder(d=20, h=base_thick, center=true);

            translate([0, 0, base_thick/2])
                cube([base_len-20, base_width, base_thick], center=true);
        }

        // Main upright
        hull() {
            translate([0, 0, center_height])
                rotate([90, 0, 0])
                    cylinder(d=housing_od, h=housing_width, center=true);

            translate([0, 0, base_thick + 5])
                cube([housing_od * 0.85, housing_width, 10], center=true);
        }

        // Front raised rim
        translate([0, -housing_width/2 - 1.25, center_height])
            rotate([90, 0, 0])
                cylinder(d=housing_od - 8, h=2.5, center=true);
    }
}

module pillow_block_bearing_housing() {
    difference() {
        body();

        // Bearing pocket
        translate([0, 0, center_height])
            rotate([90, 0, 0])
                cylinder(
                    d=bearing_od + clearance,
                    h=bearing_width + 0.8,
                    center=true
                );

        // Shaft hole
        translate([0, 0, center_height])
            rotate([90, 0, 0])
                cylinder(
                    d=bearing_id + 1,
                    h=housing_width + 8,
                    center=true
                );

        // Mounting holes
        for (x = [-bolt_spacing/2, bolt_spacing/2]) {
            translate([x, 0, -eps])
                cylinder(d=bolt_dia, h=base_thick + 2*eps);

            translate([x, 0, base_thick - counterbore_depth])
                cylinder(d=counterbore_dia, h=counterbore_depth + eps);
        }
    }
}

pillow_block_bearing_housing();

$fn = 128;

// Parameters
shaft_len      = 200;   // total length (mm)
shaft_diameter = 25;    // main shaft diameter (mm)
bearing_od     = 20;    // bearing outer diameter (mm)
bearing_len    = 30;    // bearing seat length (mm)
wall_thk       = 3;     // housing wall thickness (mm)
clearance      = 0.3;   // shaft bore clearance (mm)
base_thk       = 10;    // base thickness (mm)

// Derived dimensions
outer_d   = shaft_diameter + 2*wall_thk;
bore_d    = shaft_diameter + clearance;
pos1      = (shaft_len - 2*bearing_len)/2;       // start of first bearing seat
pos2      = pos1 + bearing_len;                  // end of first bearing seat
pos3      = pos2 + (shaft_len - 2*bearing_len);  // start of second bearing seat
pos4      = pos3 + bearing_len;                  // end of second bearing seat

module transmission_shaft_housing() {
    difference() {
        // Solid housing body: base plate + central cylinder
        union() {
            // Base plate (below shaft axis)
            translate([0, 0, -base_thk])
                cylinder(h = base_thk, d = outer_d, center = false);
            // Central cylinder housing (aligned with shaft axis)
            cylinder(h = shaft_len, d = outer_d, center = false);
        }
        // Bearing seat cavities (subtractive)
        translate([0, 0, pos1])
            cylinder(h = bearing_len, d = bearing_od, center = false);
        translate([0, 0, pos3])
            cylinder(h = bearing_len, d = bearing_od, center = false);
        // Shaft bore (through)
        translate([0, 0, -shaft_len/2])
            cylinder(h = shaft_len + 2, d = bore_d, center = false);
    }
}

transmission_shaft_housing();

// Square flanged bearing housing
// For 6204 bearing: 20mm ID, 47mm OD, 14mm width

$fn = 120;
eps = 0.05;

// Bearing
bearing_od = 47;
bearing_id = 20;
bearing_width = 14;
clearance = 0.35;

// Flange
flange_size = 86;
flange_thick = 10;
corner_radius = 8;

// Bearing boss
boss_od = 66;
boss_height = 20;

// Bolt holes
bolt_dia = 8;
bolt_spacing = 68;
counterbore_dia = 14;
counterbore_depth = 4;

module rounded_square(size, r, h) {
    hull() {
        for (x = [-size/2+r, size/2-r])
        for (y = [-size/2+r, size/2-r])
            translate([x, y, 0])
                cylinder(r=r, h=h);
    }
}

module square_flanged_bearing_housing() {
    difference() {
        union() {
            // Square flange plate
            rounded_square(flange_size, corner_radius, flange_thick);

            // Center bearing boss
            translate([0, 0, flange_thick])
                cylinder(d=boss_od, h=boss_height);

            // Raised front rim
            translate([0, 0, flange_thick + boss_height])
                cylinder(d=boss_od - 6, h=3);
        }

        // Bearing pocket
        translate([0, 0, flange_thick + boss_height - bearing_width])
            cylinder(
                d=bearing_od + clearance,
                h=bearing_width + 3 + eps
            );

        // Shaft through hole
        translate([0, 0, -eps])
            cylinder(
                d=bearing_id + 1,
                h=flange_thick + boss_height + 4
            );

        // Four mounting holes
        for (x = [-bolt_spacing/2, bolt_spacing/2])
        for (y = [-bolt_spacing/2, bolt_spacing/2]) {
            translate([x, y, -eps])
                cylinder(d=bolt_dia, h=flange_thick + 2*eps);

            translate([x, y, flange_thick - counterbore_depth])
                cylinder(d=counterbore_dia, h=counterbore_depth + eps);
        }
    }
}

square_flanged_bearing_housing();

$fn = 128;
shaft_diameter = 20;
bearing_od = 47;
bearing_width = 14;
wall_thickness = 8;
base_length = 100;
base_width = 64;
base_thickness = 8;
slot_length = 32;
mount_hole_diameter = 6.6;
slot_spacing = 64;
boss_diameter = bearing_od + 2 * wall_thickness;

module rounded_slot(length, diameter, height) {
  hull() {
    translate([-length / 2, 0, 0]) cylinder(h = height, d = diameter, center = true);
    translate([ length / 2, 0, 0]) cylinder(h = height, d = diameter, center = true);
  }
}

module take_up_bearing_housing() {
  difference() {
    union() {
      translate([0, 0, base_thickness / 2]) cube([base_length, base_width, base_thickness], center = true);
      translate([0, 0, base_thickness + boss_diameter / 2]) rotate([90, 0, 0]) cylinder(h = bearing_width + 2 * wall_thickness, d = boss_diameter, center = true);
    }
    translate([0, 0, base_thickness + boss_diameter / 2]) rotate([90, 0, 0]) cylinder(h = base_width + 4, d = bearing_od + 0.15, center = true);
    translate([0, 0, base_thickness + boss_diameter / 2]) rotate([90, 0, 0]) cylinder(h = base_width + 6, d = shaft_diameter + 0.4, center = true);
    for (x = [-slot_spacing / 2, slot_spacing / 2]) translate([x, 0, base_thickness / 2]) rounded_slot(slot_length, mount_hole_diameter, base_thickness + 2);
  }
}

take_up_bearing_housing();
